"""Snapping clock times to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span


def _check_step(step: int) -> None:
    if step <= 0 or 60 % step:
        raise ValueError(
            f"step must divide an hour: {step}"
        )


def _snap(minute: int, step: int) -> int:
    return (minute + step // 2) // step * step


def _label(span: Span, step: int) -> str:
    start = _snap(span.start, step)
    rounded = Span(start, _snap(span.end, step))
    hours, mins = divmod(rounded.minutes, 60)
    return f"{format_span(rounded)} ({hours}h {mins}m)"


# ---
def round_spans(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Label each span like 09:00-17:15 (8h 15m)."""
    _check_step(step)
    return [_label(span, step) for span in spans]

