import unittest

from hourglass.rounding import round_spans
from hourglass.parsing import parse_span


class RoundSpansTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        spans = [parse_span("09:03-17:12")]
        self.assertEqual(
            round_spans(spans, 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_one_label_per_span(self):
        spans = [parse_span("08:00-09:00")] * 2
        self.assertEqual(len(round_spans(spans, 5)), 2)

    def test_bad_steps_raise(self):
        spans = [parse_span("08:00-09:00")]
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                round_spans(spans, step)
